create table if not exists public.tjdft_dashboard_snapshots (
  id text primary key check (id = 'current'),
  snapshot jsonb not null,
  content_hash text,
  source_last_edited_time timestamptz,
  synced_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);

alter table public.tjdft_dashboard_snapshots enable row level security;

drop policy if exists "TJDFT snapshots are readable by authenticated clients" on public.tjdft_dashboard_snapshots;
create policy "TJDFT snapshots are readable by authenticated clients"
  on public.tjdft_dashboard_snapshots
  for select
  to anon, authenticated
  using (true);

create index if not exists tjdft_dashboard_snapshots_synced_at_idx
  on public.tjdft_dashboard_snapshots (synced_at desc);

